#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long long base = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long long exp = strtoll(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long long mod = strtoll(argv[3], &endptr, 10);
    if (endptr == argv[3] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    // Reduce base modulo mod, handling negative base
    base = base % mod;
    if (base < 0) base += mod;
    long long result = 1 % mod; // works for mod == 1 as well
    while (exp > 0) {
        if (exp & 1LL) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1LL;
    }
    printf("result=%lld\n", result);
    return 0;
}
